package com.bank.group.service;

import com.bank.group.model.Company;
import com.bank.group.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class GroupReportService {
    private static final Logger log = Logger.getLogger(GroupReportService.class.getName());

    public List<String> allEmployeeNames(List<Company> companies) {
        log.info(() -> "Extracting all names across " + companies.size() + " companies");
        return companies.stream()
                .flatMap(c -> c.getDepartments().stream())  // level 1: company → departments
                .flatMap(d -> d.getEmployees().stream())    // level 2: department → employees
                .map(Employee::getName)                     // final projection: employee → name
                .collect(Collectors.toList());
    }
}
