    public static void main(String[] args) {
        Company retail = new Company("NBI Retail", List.of(
            new Department("IT",    List.of(new Employee("Rajesh"), new Employee("Neha"))),
            new Department("Sales", List.of(new Employee("Priya")))
        ));
        Company wealth = new Company("NBI Wealth", List.of(
            new Department("Advisory", List.of(new Employee("Amit"), new Employee("Karan")))
        ));

        List<String> names = new GroupReportService().allEmployeeNames(List.of(retail, wealth));
        log.info(() -> "All group employees: " + names);
    }
}
